"""This file contains the Base Page Object Class for the Sim Dialogs XVI test tool. All other SimDialog Page Object
Classes are derived from this class and inherit this class's methods. """

import logging
from .. interactions import SimDialogMainFuncs
from interops.libraries.desktop import AutManager
from interops.libraries.xvi import XviAutController
from interops.libraries.squish_actions.constants import SIMDIALOGS_APP_NAME

logger = logging.getLogger(__name__)

class SimDialogs():

    def __init__(self, host_address: str ="192.168.30.4") -> None:
        # Check if squish has already attached to Sim Dialogs, if not attach to it
        if not AutManager.is_aut_running(SIMDIALOGS_APP_NAME):
            sim_dialogs_driver = XviAutController.sim_dialogs_aut(serverAddress=host_address, serverPort=4322)
            sim_dialogs_driver.attach_to_aut(launch_new_startwinaut=True)

        try:
            # Restore minimized Sim Dialogs window
            SimDialogMainFuncs.restore_sim_dialog_window_using_toplevelwindow()
            self.sim_dialog_restored = True
        except Exception as e:
            # Exception is raised if the ToplevelWindow object fails to restore the SimDialogs window
            self.sim_dialog_restored = False


    def ready(self) -> bool:
        '''
        Checks the Sim Dialogs window is ready (i.e. window is restored and not minimized)

        Returns:
            bool - True if Sim Dialogs window is restored, False otherwise
        '''
        if self.sim_dialog_restored:
            return True

        # Try restoring Sim Dialogs window again using an alternate method
        logger.info("Sim Dialogs window failed to restore on first attempt, try restoring once more...")
        self.sim_dialog_restored = SimDialogMainFuncs.restore_sim_dialog_window_on_remote_system()
        return self.sim_dialog_restored

    def minimise_sim_dialog_window(self) -> None:
        '''
        Minimises the Sim Dialog window if currently in a visible/ restored state
        '''
        if self.sim_dialog_restored:
            SimDialogMainFuncs.minimise_sim_dialog_window_using_toplevelwindow()
            self.sim_dialog_restored = False

    def restore_sim_dialog_window(self) -> None:
        '''
        Restores the Sim Dialog window if currently in a minimised state
        '''
        if self.sim_dialog_restored is False:
            SimDialogMainFuncs.restore_sim_dialog_window_using_toplevelwindow()
            self.sim_dialog_restored = True